const translations = new Map(rows.map((row) => {
  const [english, ...values] = row.split("|").map((value) => value.replaceAll("\\n", "\n"));
  if (values.length !== EXTRA_RESEARCH_LOCALES.length || values.some((value) => !value)) throw new Error(`Incomplete research translation: ${english}`);
  return [english, Object.fromEntries(EXTRA_RESEARCH_LOCALES.map((locale, index) => [locale, values[index]]))];
}));

export function readerText(language, english) {
  const locale = languageKey(language);
  if (!EXTRA_RESEARCH_LOCALES.includes(locale)) return english;
  const exact = translations.get(english)?.[locale];
  if (exact !== undefined) return exact;
  // Capitalization and Markdown prefixes do not create distinct reader terminology.
  const plain = String(english).replace(/^#+\s+/u, "");
  const key = [...translations.keys()].find((entry) => entry.toLowerCase() === plain.toLowerCase());
  if (key) return `${String(english).slice(0, String(english).length - plain.length)}${translations.get(key)[locale]}`;
  if (/^\|.*\|$/u.test(english)) return String(english).split("|").map((cell) => cell.trim() ? ` ${readerText(language, cell.trim())} ` : "").join("|");
  for (const [template, translated] of translations) {
    if (!/\{\d+\}/u.test(template)) continue;
    const indices = [];
    const pattern = template.split(/(\{\d+\})/u).map((part) => {
      if (/^\{\d+\}$/u.test(part)) { indices.push(Number(part.slice(1, -1))); return "([\\s\\S]*?)"; }
      return part.replace(/[.*+?^${}()|[\]\\]/gu, "\\$&");
    }).join("");
    const match = new RegExp(`^${pattern}$`, "u").exec(english);
    if (match) return translated[locale].replace(/\{(\d+)\}/gu, (_, index) => match[indices.indexOf(Number(index)) + 1] ?? "");
  }
  if (english === "" || /^[\s\p{N}\p{P}\p{S}]*$/u.test(english)) return english;
  const error = new Error(`Missing ${locale} research reader translation: ${english}`);
  error.code = "RESEARCH_TRANSLATION_MISSING";
  throw error;
}

export function localizedReader(language, messages) {
  const key = languageKey(language);
  if (messages?.[key] !== undefined) return messages[key];
  if (!EXTRA_RESEARCH_LOCALES.includes(key)) return messages?.en ?? "";
  const translate = (value) => {
    if (typeof value === "string") return readerText(language, value);
    if (typeof value === "function") return (...args) => readerText(language, value(...args));
    if (Array.isArray(value)) return value.map(translate);
    if (value && typeof value === "object") return Object.fromEntries(Object.entries(value).map(([name, item]) => [name, translate(item)]));
    return value;
  };
  return translate(messages?.en);
}

const SECTION_ENGLISH = Object.freeze({
  conclusion: "Conclusion", analyst_work_log: "Analyst Work Log", debate_record: "Bull/Bear Debate Record",
  master_bench: "Method-Seat Bench", instrument_structure: "Fund and Index Structure",
  market_expectations: "Market Expectations and Implied Thresholds", analyst_rating: "Analyst Rating and Target-Price Revisions",
  earnings_call: "Earnings Call Management Signals", quant: "Quant Factor / Technical Risk View", news: "News and Company / Industry Voice Signals",
  short_interest: "Short Interest / Borrow / Options Information", strategic_transaction: "Strategic Transaction or Banking Event",
  valuation: "Valuation Range", price_levels: "Price Levels", catalysts: "Key Catalysts", risks: "Major Risks", position: "Position Recommendation",
  short_term: "Short-Term 1-4 Week View", medium_term: "Medium-Term 3-6 Month View", long_term: "Long-Term 12 Month View",
  data_gaps: "Data Gaps / Unavailable Data", invalidation: "Invalidation Conditions", confidence: "Confidence", source_table: "Source Table",
});

export function researchSectionHeading(language, sectionId) {
  return readerText(language, SECTION_ENGLISH[sectionId]);
}

export function readerTemplate(language, template, ...values) {
  return readerText(language, template).replace(/\{(\d+)\}/gu, (_, index) => String(values[Number(index)] ?? ""));
}
